from PIL import Image
im=Image.open('observations/obs_0030.png').convert('RGB')
px=im.load()
def isfloor(c):
    r,g,b=c
    return abs(r-172)<30 and abs(g-163)<30 and abs(b-147)<30 and r>g>b
for u in range(0,512,32):
    top=None
    for v in range(258,512):
        if isfloor(px[u,v]):
            top=v; break
    print(u,top)
print('--- plant pot bottom scan')
for u in range(320,370,6):
    last=None
    for v in range(300,400):
        r,g,b=px[u,v]
        if r>120 and r-b>50 and r-g>40: last=v
    print(u,last,px[u,last] if last else None)
print('--- right edge green')
for u in range(495,512,4):
    for v in range(280,340):
        r,g,b=px[u,v]
        if g>r+20 and g>b+20: print(u,v,(r,g,b)); break
